  danger: ["tx.triage.chrome.progress_danger", "Danger signs"],
  days: ["tx.slice.step.duration", "Duration"],
  stool: ["tx.slice.step.stool", "Stool"],
  dehydration: ["tx.slice.step.water_loss", "Water loss"],
  result: ["tx.triage.chrome.progress_result", "Result"],
