      '<input type="number" id="days" min="1" value="' + esc(state.diarrhoeaDays) + '"' + (state.diarrhoeaDaysNotSure ? " disabled" : "") + '></div>' +
      '<button class="ghost" id="notsure">' + (state.diarrhoeaDaysNotSure ? "✓ " : "") + esc(tx("tx.diarrhoea_duration.not_sure", "Not sure")) + '</button>' +
      '<button class="primary" id="next" disabled>' + esc(tx("tx.clinical_screen.under5.continue", "Continue")) + '</button>' +
      backButton(PREV_STEP.days);
